const START_NODE = 0;

// CONTRACT for getPathsFromNodeToTarget(graph, curNode, targetNode):
//     when this call returns, the returned list holds every possible
//     path from `curNode` to `targetNode`, each written as the full
//     list of intersections along the way.
const getPathsFromNodeToTarget = (graph, curNode, targetNode) => {
    // Base cases
    if (curNode === targetNode) return [[curNode]];

    // Process node
    const allPathsFromNodeToTarget = [];

    // Recurse on neighbors
    // The streets form a DAG (no cycles), so we can never drive back to
    // an intersection already on our path — that is why no visited set
    // is needed for this traversal.
    const neighbors = graph[curNode];
    for (const neighbor of neighbors) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, it hands back every path
        // from `neighbor` to the target. Trust it, do not trace it. Every
        // path from `curNode` starts by stepping to some neighbor, so
        // putting `curNode` in front of each neighbor's guaranteed paths
        // builds exactly this function's contract.
        const pathsFromNeighborToTarget = getPathsFromNodeToTarget(
            graph,
            neighbor,
            targetNode,
        );

        for (const path of pathsFromNeighborToTarget) {
            const pathFromCurToTarget = [curNode, ...path];

            allPathsFromNodeToTarget.push(pathFromCurToTarget);
        }
    }

    return allPathsFromNodeToTarget;
};

const routesThroughCheckpoint = (graph, checkpoint) => {
    const targetNode = graph.length - 1;

    // The recursive leap of faith: trust the contract. When this
    // call returns, `allRoutes` holds every route from the start to
    // the last intersection. We do not trace inside; we just filter
    // the routes for the ones passing the checkpoint.
    const allRoutes = getPathsFromNodeToTarget(graph, START_NODE, targetNode);

    // Keep only the routes that stop by the coffee cart.
    return allRoutes.filter((route) => route.includes(checkpoint));
};

// CONTRACT for markNetworkAsVisited(visited, office, trust, minTrust):
//     when this call returns, `office` and every office reachable
//     from it through secure lines (trust scores of `minTrust` or
//     more) is in the visited set.
const markNetworkAsVisited = (visited, office, trust, minTrust) => {
    // For this problem, our base case is automatically handled
    // (our base case occurs when the current office has 0 unvisited
    // neighbor offices).

    // Process node
    visited.add(office);

    // Recurse on neighbors
    for (
        let potentialNeighborOffice = 0;
        potentialNeighborOffice < trust.length;
        potentialNeighborOffice++
    ) {
        // A direct secure line only exists when the trust score reaches
        // the threshold — a lower score means there is no edge at all.
        const isNeighbor =
            trust[office][potentialNeighborOffice] >= minTrust;

        if (!isNeighbor) continue;

        // Trust scores are symmetric, so this is an undirected graph.
        // Undirected graphs can have cycles, so we must track visited
        // offices to prevent infinite loops.
        if (visited.has(potentialNeighborOffice)) continue;

        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, this neighbor office and
        // everything reachable from it is in the visited set. Trust it,
        // do not trace it. This function already put `office` into
        // visited, and each neighbor's contract covers the offices beyond
        // it — together, that is this function's full contract, kept.
        markNetworkAsVisited(visited, potentialNeighborOffice, trust, minTrust);
    }
};

const countSecureNetworks = (trust, k) => {
    const numOffices = trust.length;

    let numNetworks = 0;
    const visited = new Set();

    for (let startOffice = 0; startOffice < numOffices; startOffice++) {
        if (visited.has(startOffice)) continue;

        numNetworks++;
        // The recursive leap of faith: trust the contract. When this
        // call returns, `startOffice` and its entire secure network are
        // in visited, so the loop can never count this network again. We
        // do not trace inside; we just count it and move on.
        markNetworkAsVisited(visited, startOffice, trust, k);
    }

    return numNetworks;
};

const NO_BOSS = 0;

const buildReportsGraph = (ids, bosses) => {
    const reportsGraph = {};

    for (let i = 0; i < ids.length; i++) {
        const employeeId = ids[i];
        const bossId = bosses[i];

        if (bossId === NO_BOSS) continue;

        const bossInGraph = reportsGraph.hasOwnProperty(bossId);
        if (!bossInGraph) reportsGraph[bossId] = [];

        reportsGraph[bossId].push(employeeId);
    }

    return reportsGraph;
};

// CONTRACT for markSubtreeAsLeaving(reportsGraph, employeeId, leaving):
//     when this call returns, `employeeId` and every employee below
//     them in the reporting tree — reports, reports of reports, and
//     so on — is in the leaving set.
const markSubtreeAsLeaving = (reportsGraph, employeeId, leaving) => {
    // Base cases
    if (leaving.has(employeeId)) return;

    // Process node
    leaving.add(employeeId);

    // Recurse on neighbors (the employee's direct reports)
    const hasReports = reportsGraph.hasOwnProperty(employeeId);
    if (!hasReports) return;

    const reports = reportsGraph[employeeId];

    for (const reportId of reports) {
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, `reportId` and everyone
        // below them is in the leaving set. Trust it, do not trace it.
        // This function already put `employeeId` into leaving, and each
        // report's contract covers that report's whole branch — together,
        // that is this function's full contract, kept.
        markSubtreeAsLeaving(reportsGraph, reportId, leaving);
    }
};

const remainingEmployees = (ids, bosses, quitId) => {
    const reportsGraph = buildReportsGraph(ids, bosses);

    // Everyone in the quitter's subtree leaves; everyone else stays.
    const leaving = new Set();
    // The recursive leap of faith: trust the contract. When this
    // call returns, the quitter and everyone below them in the tree
    // is in the leaving set. We do not trace inside; we just keep the
    // employees who are not in the set.
    markSubtreeAsLeaving(reportsGraph, quitId, leaving);

    const remaining = ids.filter((employeeId) => !leaving.has(employeeId));

    // Sort as numbers — the default sort would compare IDs as strings.
    remaining.sort((idOne, idTwo) => idOne - idTwo);

    return remaining;
};

const BOAT = 'B';

const getPositionString = (row, col) => `${row}, ${col}`;
const directions = [
    [0, 1],
    [1, 0],
    [0, -1],
    [-1, 0],
];

const isInBounds = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const rowInBounds = row >= 0 && row < numRows;
    const colInBounds = col >= 0 && col < numCols;

    return rowInBounds && colInBounds;
};

const isOnBorder = (grid, row, col) => {
    const numRows = grid.length;
    const numCols = grid[0].length;

    const onBorderRow = row === 0 || row === numRows - 1;
    const onBorderCol = col === 0 || col === numCols - 1;

    return onBorderRow || onBorderCol;
};

// CONTRACT for boatTouchesBorder(marina, row, col, visited):
//     when this call returns, every boat square connected to
//     (`row`, `col`) is in the visited set, and the returned value is
//     true if any square of that boat sits on the border of the grid.
//     If (`row`, `col`) is not a fresh boat square, it returns false
//     and nothing new goes in.
const boatTouchesBorder = (marina, row, col, visited) => {
    // Base cases
    if (!isInBounds(marina, row, col)) return false;

    const curPositionString = getPositionString(row, col);
    if (visited.has(curPositionString)) return false;

    if (marina[row][col] !== BOAT) return false;

    // Process node
    visited.add(curPositionString);

    let touchesBorder = isOnBorder(marina, row, col);

    // Recurse on potential neighbors
    for (const direction of directions) {
        const [rowChange, colChange] = direction;

        const newRow = row + rowChange;
        const newCol = col + colChange;

        // Always recurse — even after finding a border square — so the
        // whole boat gets marked as visited exactly once.
        // The recursive leap of faith, one level down: this call has
        // the SAME contract — when it returns, everything connected to
        // the neighboring square is in visited, and it reports whether it
        // found a border square. Trust it, do not trace it. This square's
        // own border check + each direction's guaranteed answer = exactly
        // this function's contract.
        const neighborTouchesBorder = boatTouchesBorder(
            marina,
            newRow,
            newCol,
            visited,
        );

        if (neighborTouchesBorder) touchesBorder = true;
    }

    return touchesBorder;
};

const countDockedBoats = (marina) => {
    const numRows = marina.length;
    const numCols = marina[0].length;

    let numDockedBoats = 0;
    const visited = new Set();

    for (let row = 0; row < numRows; row++) {
        for (let col = 0; col < numCols; col++) {
            const curPositionString = getPositionString(row, col);
            if (visited.has(curPositionString)) continue;

            if (marina[row][col] !== BOAT) continue;

            // Boats never touch each other (not even diagonally), so a
            // 4-directional DFS from here covers exactly one boat.
            // The recursive leap of faith: trust the contract. When this
            // call returns, this whole boat is in visited — the loop can
            // never see it again — and `isDocked` tells us whether the boat
            // touches the border. We do not trace inside; we just count it if
            // it is docked.
            const isDocked = boatTouchesBorder(marina, row, col, visited);
            if (isDocked) numDockedBoats++;
        }
    }

    return numDockedBoats;
};
